function validateThresholds(thresholds, availableMetricIds) {
  if (!thresholds || Object.keys(thresholds).length === 0) {
    return { valid: true };
  }

  const errors = [];
  const validated = {};

  for (const [metricId, min] of Object.entries(thresholds)) {
    if (typeof min !== 'number') {
      errors.push(`threshold for metric '${metricId}': minimum must be a number, got ${typeof min}`);
      continue;
    }
    if (min < 0 || min > 1) {
      errors.push(`threshold for metric '${metricId}': minimum must be between 0 and 1, got ${min}`);
      continue;
    }
    if (!availableMetricIds.includes(metricId)) {
      errors.push(`unknown metric '${metricId}'. Valid metrics: ${availableMetricIds.join(', ')}`);
      continue;
    }
    validated[metricId] = min;
  }

  return errors.length > 0 ? { valid: false, errors } : { valid: true, validated };
}

export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholds && Object.keys(thresholds).length > 0) {
    const availableMetricIds = evaluations.map((m) => m.id);
    const validation = validateThresholds(thresholds, availableMetricIds);

    if (!validation.valid) {
      const error = new Error('Invalid thresholds');
      error.code = 'INVALID_THRESHOLDS';
      error.details = validation.errors;
      throw error;
    }

    const thresholdResults = [];
    let allPassed = true;

    for (const [metricId, min] of Object.entries(validation.validated)) {
      const metric = evaluations.find((m) => m.id === metricId);
      const score = metric?.score;
      const passed = score !== null && score !== undefined && score >= min;
      if (!passed) allPassed = false;
      thresholdResults.push({
        metric: metricId,
        min,
        score,
        passed
      });
    }

    report.passed = allPassed;
    report.thresholds = thresholdResults;
  }

  return report;
}

