function parseThresholds(thresholdStrings?: string[]): { thresholds?: Record<string, number>; usageErrors?: string[] } {
  if (!thresholdStrings || thresholdStrings.length === 0) {
    return { thresholds: undefined };
  }

  const thresholds: Record<string, number> = {};
  const usageErrors: string[] = [];

  for (const thresholdStr of thresholdStrings) {
    const match = thresholdStr.match(/^([a-z_]+)=(.+)$/);
    if (!match) {
      usageErrors.push(`malformed threshold '${thresholdStr}': must be in format <metric>=<number>`);
      continue;
    }

    const [, metric, value] = match;
    const num = Number.parseFloat(value);
    if (Number.isNaN(num)) {
      usageErrors.push(`malformed threshold '${thresholdStr}': '${value}' is not a valid number`);
      continue;
    }

    thresholds[metric] = num;
  }

  if (usageErrors.length > 0) {
    return { usageErrors };
  }

  return { thresholds };
}

function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);
  const { thresholds, usageErrors } = parseThresholds(options.threshold);
  if (usageErrors && usageErrors.length > 0) {
    log.error('Invalid threshold options:');
    usageErrors.forEach((error) => console.error(` - ${error}`));
    process.exit(2);
  }

  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  let report: any;
  try {
    report = (Eval.generateReport as unknown as (config: unknown) => any)({
      evaluations,
      outputsPath: dataset.outputsPath,
      referencesPath: dataset.referencesPath,
      thresholds
    });
  } catch (error) {
    if (error instanceof Error && (error as any).code === 'INVALID_THRESHOLDS') {
      log.error('Invalid threshold options:');
      const details = (error as any).details as string[];
      details.forEach((detail) => console.error(` - ${detail}`));
      process.exit(2);
    }
    throw error;
  }

  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  if (report.passed === false) {
    log.error('Evaluation failed: one or more thresholds did not pass');
    process.exit(1);
  }
}

