function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);
  const { thresholds, usageErrors } = parseThresholds(options.threshold);
  if (usageErrors && usageErrors.length > 0) {
    log.error('Invalid threshold options:');
    usageErrors.forEach((error) => console.error(` - ${error}`));
    process.exit(2);
  }

  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  let report: any;
  try {
    report = (Eval.generateReport as unknown as (config: unknown) => any)({
      evaluations,
      outputsPath: dataset.outputsPath,
      referencesPath: dataset.referencesPath,
      thresholds
    });

477	function parseThresholds(thresholdStrings?: string[]): { thresholds?: Record<string, number>; usageErrors?: string[] } {
478	  if (!thresholdStrings || thresholdStrings.length === 0) {
479	    return { thresholds: undefined };
480	  }
481	
482	  const thresholds: Record<string, number> = {};
483	  const usageErrors: string[] = [];
484	
485	  for (const thresholdStr of thresholdStrings) {
486	    const match = thresholdStr.match(/^([a-z_]+)=(.+)$/);
487	    if (!match) {
488	      usageErrors.push(`malformed threshold '${thresholdStr}': must be in format <metric>=<number>`);
489	      continue;
490	    }
491	
492	    const [, metric, value] = match;
493	    const num = Number.parseFloat(value);
494	    if (Number.isNaN(num)) {
495	      usageErrors.push(`malformed threshold '${thresholdStr}': '${value}' is not a valid number`);
496	      continue;
497	    }
498	
499	    thresholds[metric] = num;
500	  }
501	
502	  if (usageErrors.length > 0) {
503	    return { usageErrors };
504	  }
505	
506	  return { thresholds };
507	}
